import React, { useEffect, useState } from 'react';
import api from '../api';

export default function Records() {
  const [records, setRecords] = useState([]);
  const [file, setFile] = useState(null);
  const [msg, setMsg] = useState('');

  const load = () => api.get('/records').then(r => setRecords(r.data));
  useEffect(() => { load(); }, []);

  const upload = async (e) => {
    e.preventDefault();
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
      await api.post('/records', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setMsg('File uploaded!');
      setFile(null);
      load();
    } catch {
      setMsg('Upload failed');
    }
  };

  return (
    <div className="mt-6">
      <h2 className="text-xl font-bold mb-4">Medical Records</h2>
      <form onSubmit={upload} className="flex gap-3 mb-6">
        <input type="file" onChange={e => setFile(e.target.files[0])} className="text-sm" />
        <button type="submit" className="btn">Upload</button>
      </form>
      {msg && <p className="text-green-600 text-sm mb-3">{msg}</p>}
      {records.length === 0 && <p className="text-gray-400">No records uploaded yet.</p>}
      <div className="space-y-2">
        {records.map(r => (
          <div key={r._id} className="border rounded p-3 flex items-center justify-between">
            <span className="text-sm">{r.filename}</span>
            <a href={`${process.env.REACT_APP_SOCKET_URL}${r.url}`} target="_blank" rel="noreferrer"
              className="text-blue-600 text-sm underline">View</a>
          </div>
        ))}
      </div>
    </div>
  );
}
